// ─── Types ────────────────────────────────────────────────────────────────

export interface ScoredPlayer {
  id: string;
  rating: number;
}

export interface BuildTeam {
  ids: string[];
  total: number;
  /** Fixed target size — balancing AVERAGES needs the final head count. */
  size: number;
}

/** One past game-night's split, newest first is NOT assumed — sorted here. */
export interface PastSplit {
  /** ms epoch of the game-night, used only for ordering. */
  startsAt: number;
  /** The teams as first drawn (`originalTeams ?? teams`). */
  teams: string[][];
}

export type BalanceStrategy = 'A' | 'B';

/**
 * Which tolerance band a split's rating gap fell into. Recorded on every split
 * so the parameters can eventually be calibrated from real weeks instead of
 * from a simulation: 'A' ≤ 0.10 excellent, 'B' ≤ 0.15 good, 'C' ≤ 0.20
 * tolerable, 'over' only reachable through the fallback.
 */
export type BalanceBand = 'A' | 'B' | 'C' | 'over';

export function balanceBand(gap: number): BalanceBand {
  if (gap <= GAP_EXCELLENT + 1e-9) return 'A';
  if (gap <= GAP_GOOD + 1e-9) return 'B';
  if (gap <= GAP_MAX + 1e-9) return 'C';
  return 'over';
}

export interface CoreInput {
  playerIds: string[];
  /** Roster id → raw rating. Missing/≤0 = unrated → NEUTRAL_RATING. */
  ratings: Record<string, number>;
  numTeams: number;
  /** Capacity per team; players beyond numTeams × perTeam are benched. */
  perTeam: number;
  /** Pair key → repeat weight, from buildPairRepeatWeights. Absent = no
   *  history, and the split is decided on balance alone. */
  pairWeights?: Record<string, number>;
  strategy?: BalanceStrategy;
  candidates?: number;
  /** Injectable for deterministic tests and for client/server parity. */
  rng?: () => number;
}

export interface CoreResult {
  /** Team rosters, ordered by team index. */
  teams: string[][];
  /** Players who did not fit under the capacity, weakest last. */
  bench: string[];
  /** Strongest team average − weakest. */
  gap: number;
  /** Total repeat weight carried by this split. */
  repeat: number;
  /** Extreme-stacking penalty (see stackPenalty). */
  stack: number;
  /** Which tolerance band `gap` fell into — recorded for later calibration. */
  band: BalanceBand;
  /** True when no candidate reached GAP_MAX and the fallback window was used. */
  fallback: boolean;
  /** How many roster ids had no rating. */
  unratedCount: number;
}

// ─── Pair history ─────────────────────────────────────────────────────────

/** Order-independent key for a pair of roster ids. */
export function pairKey(a: string, b: string): string {
  return a < b ? `${a}|${b}` : `${b}|${a}`;
}

/**
 * Turn recent game-nights into a pair → repeat-weight map.
 *
 * The window is per PAIR, not per calendar: for each pair we walk back through
 * the splits and count only the nights where BOTH players appear, up to
 * HISTORY_MEETINGS of them. A night one of them missed does not consume a slot
 * — otherwise a player who skips two weeks would look "fresh" to everyone.
 *
 * A night contributes weight only if they were on the SAME team in it; a night
 * they spent on opposite teams still consumes a slot (they met, and that meeting
 * is evidence of nothing repeating). Splits with no usable teams must be
 * filtered out by the caller — a night we know nothing about must not consume a
 * slot either.
 *
 * Guests are skipped entirely: their ids are per-game and mean nothing here.
 */
export function buildPairRepeatWeights(
  splits: PastSplit[],
): Record<string, number> {
  const ordered = splits
    .filter((s) => s.teams.some((t) => t.length > 0))
    .slice()
    .sort((a, b) => b.startsAt - a.startsAt);

  const weights: Record<string, number> = {};
  const meetings: Record<string, number> = {};

  for (const split of ordered) {
    // roster id → team index, for real (non-guest) players only.
    const teamOf: Record<string, number> = {};
    const members: string[] = [];
    split.teams.forEach((team, idx) => {
      for (const id of team) {
        if (!id || id.startsWith(GUEST_PREFIX)) continue;
        if (teamOf[id] !== undefined) continue; // defensive: id in two teams
        teamOf[id] = idx;
        members.push(id);
      }
    });
    for (let i = 0; i < members.length; i++) {
      for (let j = i + 1; j < members.length; j++) {
        const key = pairKey(members[i], members[j]);
        const seen = meetings[key] ?? 0;
        if (seen >= HISTORY_MEETINGS) continue;
        meetings[key] = seen + 1;
        if (teamOf[members[i]] === teamOf[members[j]]) {
          weights[key] = (weights[key] ?? 0) + REPEAT_WEIGHTS[seen];
        }
      }
    }
  }
  return weights;
}

/** Total repeat weight carried by a split: every within-team pair, summed. */
export function repeatPenalty(
  teams: BuildTeam[],
  pairWeights: Record<string, number> | undefined,
): number {
  if (!pairWeights) return 0;
  let total = 0;
  for (const t of teams) {
    for (let i = 0; i < t.ids.length; i++) {
      for (let j = i + 1; j < t.ids.length; j++) {
        total += pairWeights[pairKey(t.ids[i], t.ids[j])] ?? 0;
      }
    }
  }
  return total;
}

/** Candidate membership and weights stay fixed while refinement swaps players.
 * Compile pair keys once, preserving the exact pair-summation order and RNG. */
function repeatScorer(teams: BuildTeam[], weights: Record<string, number>): (teams: BuildTeam[]) => number {
  const ids = teams.flatMap(team => team.ids);
  const table: Record<string, Record<string, number>> = Object.create(null);
  for (const id of ids) table[id] = Object.create(null);
  for (let i = 0; i < ids.length; i++) {
    for (let j = i + 1; j < ids.length; j++) {
      const value = weights[pairKey(ids[i], ids[j])] ?? 0;
      table[ids[i]][ids[j]] = value;
      table[ids[j]][ids[i]] = value;
    }
  }
  return current => {
    let total = 0;
    for (const team of current) {
      for (let i = 0; i < team.ids.length; i++) {
        const row = table[team.ids[i]];
        for (let j = i + 1; j < team.ids.length; j++) total += row[team.ids[j]];
      }
    }
    return total;
  };
}

/**
 * A copy of the pair weights with each entry scaled by an independent random
 * factor in [1 − SEARCH_JITTER, 1 + SEARCH_JITTER]. Used to steer one restart
 * of the search; results are always scored on the true weights.
 */
function jitterWeights(
  weights: Record<string, number>,
  rng: () => number,
): Record<string, number> {
  const out: Record<string, number> = {};
  for (const key in weights) {
    out[key] = weights[key] * (1 + (rng() * 2 - 1) * SEARCH_JITTER);
  }
  return out;
}

/** Repeat weight a single player carries against one team's current members. */
function repeatOfPlayerIn(
  id: string,
  team: BuildTeam,
  pairWeights: Record<string, number> | undefined,
): number {
  if (!pairWeights) return 0;
  let total = 0;
  for (const other of team.ids) {
    if (other === id) continue;
    total += pairWeights[pairKey(id, other)] ?? 0;
  }
  return total;
}

// ─── Balance primitives ───────────────────────────────────────────────────

/** In-place Fisher–Yates shuffle using the caller's RNG. */
function shuffleInPlace<T>(arr: T[], rng: () => number): void {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    const tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }
}

/**
 * Team sizes, as even as possible, capped at `capacity` each. The remainder
 * goes to a RANDOM subset of teams, so "team א is always the bigger one" never
 * becomes a fixed pattern.
 */
export function splitSizes(
  count: number,
  numTeams: number,
  capacity: number,
  rng: () => number,
): number[] {
  const placed = Math.min(count, numTeams * capacity);
  const base = Math.floor(placed / numTeams);
  const extra = placed % numTeams;
  const order: number[] = [];
  for (let i = 0; i < numTeams; i++) order.push(i);
  shuffleInPlace(order, rng);
  const sizes: number[] = [];
  for (let i = 0; i < numTeams; i++) sizes.push(base);
  for (let i = 0; i < extra; i++) sizes[order[i]] += 1;
  return sizes;
}

export function averageOf(t: BuildTeam): number {
  return t.ids.length > 0 ? t.total / t.ids.length : NEUTRAL_RATING;
}

/** Strongest team average minus weakest. Zero = perfectly balanced. */
export function spreadOf(teams: BuildTeam[]): number {
  let min = Infinity;
  let max = -Infinity;
  for (const t of teams) {
    const a = averageOf(t);
    if (a < min) min = a;
    if (a > max) max = a;
  }
  return max - min;
}

/**
 * The strongest and weakest ends of the roster, TIE-INCLUSIVE: everyone at or
 * above the Nth-highest rating, and everyone at or below the Nth-lowest. Taking
 * literally N ids would let a tie at the cut-off hide a pile-up.
 */
export function extremeSets(
  scored: ScoredPlayer[],
  numTeams: number,
): { top: Record<string, true>; bottom: Record<string, true> } {
  const sorted = scored.map((p) => p.rating).sort((a, b) => b - a);
  const topCut = sorted[Math.min(numTeams, sorted.length) - 1];
  const bottomCut = sorted[Math.max(0, sorted.length - numTeams)];
  const top: Record<string, true> = {};
  const bottom: Record<string, true> = {};
  for (const p of scored) {
    if (p.rating >= topCut) top[p.id] = true;
    else if (p.rating <= bottomCut) bottom[p.id] = true;
  }
  return { top, bottom };
}

/**
 * How badly a split stacks the extremes: the sum of SQUARED per-team counts of
 * the top (and bottom) players, smallest when they are spread one per team.
 * Squared and not `max(0, n − 1)`, which scores 3/1/1 and 2/2/1 identically.
 */
export function stackPenalty(
  teams: BuildTeam[],
  top: Record<string, true>,
  bottom: Record<string, true>,
): number {
  let penalty = 0;
  for (const t of teams) {
    let nTop = 0;
    let nBottom = 0;
    for (const id of t.ids) {
      if (top[id]) nTop += 1;
      else if (bottom[id]) nBottom += 1;
    }
    penalty += nTop * nTop + nBottom * nBottom;
  }
  return penalty;
}

/** Pairwise squared differences between corresponding skill ranks. Equal
 * sizes compare strongest with strongest, second with second, etc. Unequal
 * sizes interpolate at the same relative ranks, including both endpoints. */
function sortedProfilePenalty(profiles: number[][]): number {
  const ranks = Math.max(1, ...profiles.map(p => p.length));
  let penalty = 0;
  for (let rank = 0; rank < ranks; rank++) {
    const q = ranks === 1 ? 0 : rank / (ranks - 1);
    const values = profiles.map(p => {
      if (!p.length) return NEUTRAL_RATING;
      const at = q * (p.length - 1), low = Math.floor(at), high = Math.ceil(at);
      return p[low] + (p[high] - p[low]) * (at - low);
    });
    for (let a = 0; a < values.length; a++) {
      for (let b = a + 1; b < values.length; b++) penalty += (values[a] - values[b]) ** 2;
    }
  }
  return penalty;
}

export function ratingProfilePenalty(teams: BuildTeam[], rating: (id: string) => number): number {
  return sortedProfilePenalty(teams.map(t => t.ids.map(rating).sort((a, b) => b - a)));
}

type PriorityQuality = [gap: number, stack: number, profile: number, repeat: number];

/** Lower-priority terms can NEVER pay for a worse higher-priority term. */
function comparePriority(a: PriorityQuality, b: PriorityQuality): number {
  for (let i = 0; i < a.length; i++) {
    if (a[i] < b[i] - 1e-9) return -1;
    if (a[i] > b[i] + 1e-9) return 1;
  }
  return 0;
}

function priorityQuality(
  teams: BuildTeam[], rating: (id: string) => number,
  top: Record<string, true>, bottom: Record<string, true>,
  pairWeights?: Record<string, number>,
): PriorityQuality {
  return [spreadOf(teams), stackPenalty(teams, top, bottom), ratingProfilePenalty(teams, rating), repeatPenalty(teams, pairWeights)];
}

/** Match the approved small-roster simulation without unbounded production work. */
function exactPrioritySplit(
  scored: ScoredPlayer[], sizes: number[], rating: (id: string) => number,
  top: Record<string, true>, bottom: Record<string, true>,
  pairWeights: Record<string, number> | undefined, rng: () => number,
): BuildTeam[] | undefined {
  const n = scored.length;
  if (n > EXACT_MAX_PLAYERS || n === 0 || sizes.some(size => size === 0)) return undefined;
  const factorial = (v: number) => { let value = 1; for (let i = 2; i <= v; i++) value *= i; return value; };
  const counts: Record<number, number> = {};
  let partitions = factorial(n);
  for (const size of sizes) { partitions /= factorial(size); counts[size] = (counts[size] ?? 0) + 1; }
  for (const count of Object.values(counts)) partitions /= factorial(count);
  if (partitions > EXACT_MAX_PARTITIONS + 1e-6) return undefined;

  interface Group { mask: number; first: number; team: BuildTeam; profile: number[]; stack: number; repeat: number }
  const cache = new Map<number, Group>();
  const group = (indices: number[]): Group => {
    const mask = indices.reduce((value, i) => value | (1 << i), 0);
    const previous = cache.get(mask);
    if (previous) return previous;
    const ids = indices.map(i => scored[i].id);
    const team = { ids, size: ids.length, total: ids.reduce((sum, id) => sum + rating(id), 0) };
    const result = { mask, first: indices[0], team, profile: ids.map(rating).sort((a, b) => b - a),
      stack: stackPenalty([team], top, bottom), repeat: repeatPenalty([team], pairWeights) };
    cache.set(mask, result);
    return result;
  };
  const targets = sizes.slice().sort((a, b) => a - b);
  const bySize = new Map<number, Group[]>();
  for (const size of new Set(targets)) {
    const combinations: Group[] = [], indices: number[] = [];
    const choose = (start: number) => {
      if (indices.length === size) { combinations.push(group(indices)); return; }
      for (let i = start; i <= n - (size - indices.length); i++) {
        indices.push(i); choose(i + 1); indices.pop();
      }
    };
    choose(0); bySize.set(size, combinations);
  }
  // A cheap valid upper bound avoids expensive profile work before the first
  // excellent partition happens to appear in enumeration order.
  const initial = greedyBuild(scored, sizes, rng);
  refineSwaps(initial.teams, rating, spreadOf, rng);
  let best = priorityQuality(initial.teams, rating, top, bottom, pairWeights);
  let selected: BuildTeam[] | undefined, ties = 0;
  const picked: Group[] = [];
  const uniformRatings = scored.every(p => p.rating === scored[0].rating);
  const evaluate = () => {
    let low = Infinity, high = -Infinity, stack = 0, repeat = 0;
    for (const g of picked) {
      const average = averageOf(g.team);
      low = Math.min(low, average); high = Math.max(high, average);
      stack += g.stack; repeat += g.repeat;
    }
    const gap = high - low;
    if (gap > best[0] + 1e-9) return;
    if (Math.abs(gap - best[0]) <= 1e-9 && stack > best[1]) return;
    const profile = uniformRatings ? 0 : sortedProfilePenalty(picked.map(g => g.profile));
    const quality: PriorityQuality = [gap, stack, profile, repeat];
    const comparison = comparePriority(quality, best);
    if (comparison > 0) return;
    if (comparison < 0) { best = quality; ties = 0; }
    // One unbiased draw across distinct unlabeled partitions, with no list of
    // hundreds of thousands of tied splits retained in memory.
    if (rng() < 1 / ++ties) selected = picked.map(g => g.team);
  };
  const visit = (remaining: number, depth: number, previousFirst: number) => {
    const size = targets[depth];
    const minimumFirst = depth > 0 && targets[depth - 1] === size ? previousFirst : -1;
    if (depth === targets.length - 1) {
      const last = cache.get(remaining)!;
      if (last.first <= minimumFirst) return;
      picked.push(last); evaluate(); picked.pop(); return;
    }
    const equalRemainder = size === targets[targets.length - 1];
    const anchor = remaining & -remaining;
    for (const candidate of bySize.get(size)!) {
      if (candidate.first <= minimumFirst || (equalRemainder && !(candidate.mask & anchor)) ||
          (candidate.mask & remaining) !== candidate.mask) continue;
      picked.push(candidate);
      visit(remaining ^ candidate.mask, depth + 1, candidate.first);
      picked.pop();
    }
  };
  visit((1 << n) - 1, 0, -1);
  return selected;
}

/** Bounded local descent for larger rosters, with the same lexicographic rule. */
function refinePrioritySwaps(
  teams: BuildTeam[], rating: (id: string) => number,
  top: Record<string, true>, bottom: Record<string, true>,
  pairWeights: Record<string, number> | undefined, rng: () => number,
): void {
  for (let pass = 0; pass < MAX_REFINE_PASSES; pass++) {
    const current = priorityQuality(teams, rating, top, bottom, pairWeights);
    let best = current;
    let moves: { i: number; j: number; a: number; b: number }[] = [];
    for (let i = 0; i < teams.length; i++) for (let j = i + 1; j < teams.length; j++) {
      for (let a = 0; a < teams[i].ids.length; a++) for (let b = 0; b < teams[j].ids.length; b++) {
        applySwap(teams[i], a, teams[j], b, rating);
        // Most swaps are rejected on the cheap first term, before sorting profiles.
        if (spreadOf(teams) <= best[0] + 1e-9) {
          const quality = priorityQuality(teams, rating, top, bottom, pairWeights);
          const comparison = comparePriority(quality, best);
          if (comparison < 0) { best = quality; moves = [{ i, j, a, b }]; }
          else if (comparison === 0 && comparePriority(quality, current) < 0) moves.push({ i, j, a, b });
        }
        applySwap(teams[i], a, teams[j], b, rating);
      }
    }
    if (!moves.length) return;
    const move = moves[Math.floor(rng() * moves.length)];
    applySwap(teams[move.i], move.a, teams[move.j], move.b, rating);
  }
}

function balancePriority(
  scored: ScoredPlayer[], perTeam: number, numTeams: number,
  rating: (id: string) => number, top: Record<string, true>, bottom: Record<string, true>,
  pairWeights: Record<string, number> | undefined, candidates: number, rng: () => number,
  unratedCount: number,
): CoreResult {
  const shuffled = scored.slice();
  shuffleInPlace(shuffled, rng);
  shuffled.sort((a, b) => b.rating - a.rating);
  const placed = shuffled.slice(0, numTeams * perTeam), bench = shuffled.slice(numTeams * perTeam);
  const sizes = splitSizes(placed.length, numTeams, perTeam, rng);
  const uniform = !pairWeights && placed.every(p => p.rating === placed[0]?.rating);
  let teams: BuildTeam[] | undefined;
  if (uniform) {
    const draw = placed.slice(); shuffleInPlace(draw, rng);
    let offset = 0;
    teams = sizes.map(size => {
      const members = draw.slice(offset, offset + size); offset += size;
      return { ids: members.map(p => p.id), size, total: members.reduce((sum, p) => sum + p.rating, 0) };
    });
  } else teams = exactPrioritySplit(placed, sizes, rating, top, bottom, pairWeights, rng);
  if (!teams) {
    let best: PriorityQuality = [Infinity, Infinity, Infinity, Infinity];
    let ties = 0;
    const seen = new Set<string>();
    for (let k = 0; k < Math.max(1, candidates); k++) {
      const built = greedyBuild(placed, sizes, rng, pairWeights ? jitterWeights(pairWeights, rng) : undefined);
      refineSwaps(built.teams, rating, spreadOf, rng);
      refinePrioritySwaps(built.teams, rating, top, bottom, pairWeights, rng);
      const key = built.teams.map(t => t.ids.slice().sort().join(',')).sort().join('|');
      if (seen.has(key)) continue;
      seen.add(key);
      const quality = priorityQuality(built.teams, rating, top, bottom, pairWeights);
      const comparison = comparePriority(quality, best);
      if (comparison > 0) continue;
      if (comparison < 0) { best = quality; ties = 0; }
      if (rng() < 1 / ++ties) teams = built.teams;
    }
  }
  const result = teams!;
  // Color/team-index assignment must not privilege a fixed subset of the roster.
  shuffleInPlace(result, rng);
  const gap = spreadOf(result);
  return { teams: result.map(t => t.ids.slice()), bench: bench.map(p => p.id), gap,
    repeat: repeatPenalty(result, pairWeights), stack: stackPenalty(result, top, bottom),
    band: balanceBand(gap), fallback: gap > GAP_MAX + 1e-9, unratedCount };
}

/**
 * The balance term, in cost units. Continuous and progressively steeper, so
 * there is no cliff at a zone edge: 0.099 and 0.101 cost almost the same, while
 * 0.19 costs a great deal more than 0.09.
 *
 *   0.00–0.10 (excellent) → 0.00–0.15   slope  1.5 / rating point
 *   0.10–0.15 (good)      → 0.15–0.50   slope  7.0
 *   0.15–0.20 (tolerable) → 0.50–1.20   slope 14.0
 *   above the ceiling     → steep, finite, so a descent can climb back down
 */
export function balancePenalty(gap: number): number {
  if (gap <= GAP_EXCELLENT) return 0.15 * (gap / GAP_EXCELLENT);
  if (gap <= GAP_GOOD) {
    return 0.15 + 0.35 * ((gap - GAP_EXCELLENT) / (GAP_GOOD - GAP_EXCELLENT));
  }
  if (gap <= GAP_MAX) {
    return 0.5 + 0.7 * ((gap - GAP_GOOD) / (GAP_MAX - GAP_GOOD));
  }
  return 1.2 + 6 * (gap - GAP_MAX);
}

/** Repeat points worth one unit of cost, for a split of this shape. */
export function repeatScale(teams: BuildTeam[]): number {
  let pairs = 0;
  for (const t of teams) pairs += (t.ids.length * (t.ids.length - 1)) / 2;
  return Math.max(1, REPEAT_SCALE_PER_PAIR * pairs);
}

// ─── Search ───────────────────────────────────────────────────────────────

/**
 * One greedy pass: strongest player first, into whichever team is furthest
 * below its share. `total / size` (not `total`) is the yardstick — that is what
 * balances averages rather than sums, so a team carrying an extra player is
 * allowed a bigger sum.
 *
 * With pair history present, ties between equally-hungry teams are broken
 * toward the team the player shares the LEAST history with, which seeds the
 * search in a varied place instead of leaving it all to the refinement.
 */
export function greedyBuild(
  scored: ScoredPlayer[],
  sizes: number[],
  rng: () => number,
  pairWeights?: Record<string, number>,
): { teams: BuildTeam[]; bench: ScoredPlayer[] } {
  const teams: BuildTeam[] = sizes.map((size) => ({ ids: [], total: 0, size }));
  const players = scored.slice();
  shuffleInPlace(players, rng); // varies the order inside every tied-rating bucket
  players.sort((a, b) => b.rating - a.rating); // stable → the shuffle survives

  const bench: ScoredPlayer[] = [];
  for (const p of players) {
    const open = teams.filter((t) => t.ids.length < t.size);
    if (open.length === 0) {
      bench.push(p);
      continue;
    }
    open.sort((a, b) => {
      const da = a.total / Math.max(1, a.size);
      const db = b.total / Math.max(1, b.size);
      if (Math.abs(da - db) > 1e-9) return da - db;
      const ra = repeatOfPlayerIn(p.id, a, pairWeights);
      const rb = repeatOfPlayerIn(p.id, b, pairWeights);
      if (Math.abs(ra - rb) > 1e-9) return ra - rb;
      if (a.ids.length !== b.ids.length) return a.ids.length - b.ids.length;
      return rng() - 0.5;
    });
    open[0].ids.push(p.id);
    open[0].total += p.rating;
  }
  return { teams, bench };
}

/** Swap two players between teams, keeping the running totals in step. */
function applySwap(
  ti: BuildTeam,
  a: number,
  tj: BuildTeam,
  b: number,
  rating: (id: string) => number,
): void {
  const ida = ti.ids[a];
  const idb = tj.ids[b];
  ti.ids[a] = idb;
  tj.ids[b] = ida;
  ti.total += rating(idb) - rating(ida);
  tj.total += rating(ida) - rating(idb);
}

/**
 * Steepest-descent refinement against whatever `cost` the caller cares about.
 * Team sizes are preserved, so it can only improve the split. Among swaps that
 * improve by the same amount it picks at random — always taking the first in
 * scan order made every descent drain into the same handful of splits.
 */
export function refineSwaps(
  teams: BuildTeam[],
  rating: (id: string) => number,
  cost: (t: BuildTeam[]) => number,
  rng: () => number,
): void {
  for (let pass = 0; pass < MAX_REFINE_PASSES; pass++) {
    let bestGain = 0;
    let best: { i: number; j: number; a: number; b: number }[] = [];
    const current = cost(teams);
    for (let i = 0; i < teams.length; i++) {
      for (let j = i + 1; j < teams.length; j++) {
        const ti = teams[i];
        const tj = teams[j];
        for (let a = 0; a < ti.ids.length; a++) {
          for (let b = 0; b < tj.ids.length; b++) {
            // Try it for real and undo — the cost depends on WHO sits where
            // (stacking, pair history), not just on the totals.
            applySwap(ti, a, tj, b, rating);
            const gain = current - cost(teams);
            applySwap(ti, a, tj, b, rating);
            if (gain <= 1e-9) continue;
            if (gain > bestGain + 1e-9) {
              bestGain = gain;
              best = [{ i, j, a, b }];
            } else if (gain >= bestGain - 1e-9) {
              best.push({ i, j, a, b });
            }
          }
        }
      }
    }
    if (best.length === 0) return;
    const pick = best[Math.floor(rng() * best.length)];
    applySwap(teams[pick.i], pick.a, teams[pick.j], pick.b, rating);
  }
}

/**
 * Random walk through the splits that are as good as the one we picked.
 *
 * "As good" is one budget in one currency: a move is allowed while the total
 * cost (balance + repeats) stays within `budget` of where the walk STARTED,
 * the gap stays under `maxGap`, and stacking never worsens. The budget is
 * measured from the starting cost, not from the current one, so a long walk
 * can't creep away one epsilon at a time.
 *
 * Without this the split is deterministic. Once history guides both the greedy
 * seeding and the refinement, all 64 candidates converge on the same answer —
 * measured, before this existed: 200 presses produced pairs that appeared
 * 200/200 times and 55 of 105 possible pairings that never occurred at all.
 * Pressing "regenerate" has to be able to return something else.
 */
export function wander(
  teams: BuildTeam[],
  rating: (id: string) => number,
  top: Record<string, true>,
  bottom: Record<string, true>,
  pairWeights: Record<string, number> | undefined,
  maxGap: number,
  steps: number,
  budget: number,
  rng: () => number,
): void {
  const scale = repeatScale(teams);
  const costNow = () =>
    balancePenalty(spreadOf(teams)) + repeatPenalty(teams, pairWeights) / scale;
  const baseStack = stackPenalty(teams, top, bottom);
  const ceiling = costNow() + budget;

  for (let s = 0; s < steps; s++) {
    const moves: { i: number; j: number; a: number; b: number }[] = [];
    for (let i = 0; i < teams.length; i++) {
      for (let j = i + 1; j < teams.length; j++) {
        const ti = teams[i];
        const tj = teams[j];
        for (let a = 0; a < ti.ids.length; a++) {
          for (let b = 0; b < tj.ids.length; b++) {
            applySwap(ti, a, tj, b, rating);
            const ok =
              spreadOf(teams) <= maxGap + 1e-9 &&
              stackPenalty(teams, top, bottom) <= baseStack &&
              costNow() <= ceiling + 1e-9;
            applySwap(ti, a, tj, b, rating);
            if (ok) moves.push({ i, j, a, b });
          }
        }
      }
    }
    if (moves.length === 0) return;
    const m = moves[Math.floor(rng() * moves.length)];
    applySwap(teams[m.i], m.a, teams[m.j], m.b, rating);
  }
}

// ─── The split ────────────────────────────────────────────────────────────

interface Candidate {
  teams: BuildTeam[];
  bench: ScoredPlayer[];
  gap: number;
  repeat: number;
  stack: number;
}

/**
 * Default A orders average gap, extreme distribution, full skill profile, then
 * pair history. Small bounded problems are solved exactly; larger ones use
 * bounded restarts. B retains the historical comparison model below.
 */
export function balanceCore(input: CoreInput): CoreResult {
  const rng = input.rng ?? Math.random;
  const strategy: BalanceStrategy = input.strategy ?? 'A';
  const pairWeights = input.pairWeights;

  // Dedupe FIRST: a duplicate id would otherwise be placed on two teams.
  const seen: Record<string, true> = {};
  const playerIds: string[] = [];
  for (const id of input.playerIds) {
    if (!id || seen[id]) continue;
    seen[id] = true;
    playerIds.push(id);
  }
  const numTeams = Math.max(1, Math.min(input.numTeams, playerIds.length));

  let unratedCount = 0;
  const scored: ScoredPlayer[] = playerIds.map((id) => {
    const known = input.ratings[id];
    if (typeof known === 'number' && known > 0) {
      return { id, rating: normalizeRating(known) };
    }
    unratedCount += 1;
    return { id, rating: NEUTRAL_RATING };
  });
  const ratingOf = (id: string) => {
    const known = input.ratings[id];
    return typeof known === 'number' && known > 0
      ? normalizeRating(known)
      : NEUTRAL_RATING;
  };

  const { top, bottom } = extremeSets(scored, numTeams);
  const perTeam = Math.max(1, input.perTeam);
  const count = input.candidates ?? CANDIDATES;

  if (strategy === 'A') {
    return balancePriority(scored, perTeam, numTeams, ratingOf, top, bottom, pairWeights, count, rng, unratedCount);
  }

  const pool: Candidate[] = [];
  for (let k = 0; k < count; k++) {
    // Each restart searches with slightly different priorities (see
    // SEARCH_JITTER) so the pool holds real alternatives, not 64 copies of one
    // answer. Scoring below always uses the true weights.
    const searchWeights = pairWeights
      ? jitterWeights(pairWeights, rng)
      : undefined;
    const built = greedyBuild(
      scored,
      splitSizes(scored.length, numTeams, perTeam, rng),
      rng,
      searchWeights,
    );
    const teams = built.teams;
    // Phase 1 — get into the fair region on rating + stacking alone. Chasing
    // variety before the split is balanced just wastes the descent.
    refineSwaps(
      teams,
      ratingOf,
      (t) => spreadOf(t) + STACK_WEIGHT * stackPenalty(t, top, bottom),
      rng,
    );
    // Phase 2 — trade INSIDE the fair region for variety. The two strategies
    // differ only in what they are willing to trade.
    if (searchWeights) {
      const scale = repeatScale(teams);
      const scoreRepeats = repeatScorer(teams, searchWeights);
      refineSwaps(
        teams,
        ratingOf,
        // B keeps its historical policy for controlled comparisons.
        (t) =>
              scoreRepeats(t) / scale +
              100 * Math.max(0, spreadOf(t) - GAP_MAX) +
              STACK_WEIGHT * stackPenalty(t, top, bottom),
        rng,
      );
    }
    pool.push({
      teams,
      bench: built.bench,
      gap: spreadOf(teams),
      repeat: repeatPenalty(teams, pairWeights),
      stack: stackPenalty(teams, top, bottom),
    });
  }

  // Balance constraint. Normally the ceiling; when no candidate can reach it,
  // the window opens just above the best gap this roster allows.
  const minGap = Math.min(...pool.map((c) => c.gap));
  const fallback = minGap > GAP_MAX;
  const gapLimit = fallback ? minGap + FALLBACK_MARGIN : GAP_MAX;
  let eligible = pool.filter((c) => c.gap <= gapLimit + 1e-9);
  if (eligible.length === 0) eligible = pool; // never fail to produce a split

  // Stacking stays a filter, not a currency: variety may not buy a pile-up of
  // the strongest players. Relaxed by one step only if it would leave too few
  // splits to choose between (which would cost the variety we came for).
  const minStack = Math.min(...eligible.map((c) => c.stack));
  let unstacked = eligible.filter((c) => c.stack === minStack);
  if (unstacked.length < 8) {
    unstacked = eligible.filter((c) => c.stack <= minStack + 2);
  }

  const chosen = pickStrategyB(unstacked, rng);

  wander(
    chosen.teams,
    ratingOf,
    top,
    bottom,
    pairWeights,
    Math.min(gapLimit, chosen.gap + WANDER_GAP_SLACK),
    WANDER_STEPS,
    COST_EPSILON,
    rng,
  );

  const finalGap = spreadOf(chosen.teams);
  return {
    teams: chosen.teams.map((t) => t.ids.slice()),
    bench: chosen.bench.map((p) => p.id),
    gap: finalGap,
    band: balanceBand(finalGap),
    repeat: repeatPenalty(chosen.teams, pairWeights),
    stack: stackPenalty(chosen.teams, top, bottom),
    fallback,
    unratedCount,
  };
}

/** One entry per distinct composition — 64 copies of the same split are one
 *  choice, not 64. */
function distinct(pool: Candidate[]): Candidate[] {
  const seen: Record<string, true> = {};
  const out: Candidate[] = [];
  for (const c of pool) {
    const key = c.teams
      .map((t) => t.ids.slice().sort().join(','))
      .sort()
      .join('|');
    if (seen[key]) continue;
    seen[key] = true;
    out.push(c);
  }
  return out;
}

/**
 * Strategy B — balance purely as a constraint (already applied by the caller),
 * then fewest repeats wins, then the smaller gap breaks the tie. Repeats are
 * bucketed so that noise below one weak meeting doesn't decide the split.
 */
function pickStrategyB(pool: Candidate[], rng: () => number): Candidate {
  const unique = distinct(pool);
  const bucket = (c: Candidate) => Math.round(c.repeat / REPEAT_BUCKET);
  const bestBucket = Math.min(...unique.map(bucket));
  const inBucket = unique.filter((c) => bucket(c) === bestBucket);
  const bestGap = Math.min(...inBucket.map((c) => c.gap));
  const finalists = inBucket
    .filter((c) => c.gap <= bestGap + GAP_EPSILON)
    .slice(0, FINALISTS);
  return finalists[Math.floor(rng() * finalists.length)] ?? unique[0];
}
